<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {NAlert,NButton,NDrawer,NDrawerContent,NEmpty,NForm,NFormItem,NInput,NSelect,NSpace,NTag,NCheckbox,NCheckboxGroup,NPopconfirm} from 'naive-ui';
import ResourceDetails from './ResourceDetails.vue';
import InfoHint from '../../shared/ui/InfoHint.vue';
import {useNarrowViewport} from '../../shared/ui/useNarrowViewport';
import type {ManagedResource as Resource,ResourceVersion} from './resource-presentation';
import {api,ApiError,errorMessage} from '../../shared/api';
const props=defineProps<{workspaceId:string;kind:'skills'|'mcp';disabled:boolean}>();
const emit=defineEmits<{busyChanged:[boolean];sessionExpired:[]}>();

const rows=ref<Resource[]>([]),loading=ref(false),busy=ref(false),loaded=ref(false),error=ref(''),notice=ref(''),show=ref(false),editing=ref<Resource|null>(null),versions=ref<ResourceVersion[]>([]),details=ref<Resource|null>(null);
const narrow=useNarrowViewport(),detailLoading=ref(false),detailError=ref('');let detailRequest=0;
const base=computed(()=>`/workspaces/${encodeURIComponent(props.workspaceId)}`),title=computed(()=>props.kind==='skills'?'Skills':'MCP');
const query=ref(''),statusFilter=ref<'all'|'enabled'|'disabled'>('all');
const filteredRows=computed(()=>rows.value.filter(row=>(statusFilter.value==='all'||row.enabled===(statusFilter.value==='enabled'))&&(!query.value.trim()||`${row.name} ${row.description??''}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase()))));
const source=ref('zip'),file=ref<File|null>(null),gitUrl=ref(''),gitRef=ref('HEAD'),gitPath=ref('');
const name=ref(''),endpoint=ref(''),authKind=ref('none'),header=ref('x-api-key'),secret=ref(''),receipt=ref(''),tools=ref<{name:string;description:string}[]>([]),allowed=ref<string[]>([]);
let controller=new AbortController(),generation=0;const operationId=ref<string>(crypto.randomUUID());
function selectFile(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null;operationId.value=crypto.randomUUID();}
watch([busy,show],()=>emit('busyChanged',busy.value||show.value),{flush:'sync'});
watch([name,endpoint,authKind,header,secret],()=>{receipt.value='';tools.value=[];allowed.value=[];});
async function run(fn:(signal:AbortSignal)=>Promise<void>){if(busy.value||props.disabled)return;const current=generation;busy.value=true;error.value='';notice.value='';try{await fn(controller.signal);}catch(e){if(current===generation){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');if(e instanceof ApiError&&e.status===403){rows.value=[];show.value=false;}}}finally{if(current===generation)busy.value=false;}}
async function read(signal:AbortSignal){const result=await api<{skills?:Resource[];servers?:Resource[]}>(`${base.value}/${props.kind==='skills'?'skills':'mcp-resources'}`,signal);if(!signal.aborted){rows.value=result.skills??result.servers??[];loaded.value=true;}}
async function load(){loading.value=true;try{await run(read);}finally{loading.value=false;}}
function open(item:Resource|null=null){details.value=null;detailRequest++;detailLoading.value=false;editing.value=item;name.value=item?.name??'';endpoint.value=item?.endpoint??'';authKind.value=item?.auth?.kind??'none';header.value=item?.auth?.header||'x-api-key';secret.value='';receipt.value='';tools.value=[];allowed.value=[];file.value=null;gitUrl.value='';gitRef.value='HEAD';gitPath.value='';operationId.value=crypto.randomUUID();show.value=true;}
function close(){if(busy.value)return;show.value=false;secret.value='';file.value=null;receipt.value='';}
async function discover(){await run(async signal=>{const value=await api<{receipt:string;tools:{name:string;description:string}[]}>(`${base.value}/mcp-resources/discover`,signal,{...(editing.value?{id:editing.value.id,expectedVersion:editing.value.version}:{}),name:name.value,endpoint:endpoint.value,authKind:authKind.value,...(authKind.value==='header'?{header:header.value}:{}),...(secret.value?{secret:secret.value}:{})});if(signal.aborted)return;receipt.value=value.receipt;tools.value=value.tools;allowed.value=value.tools.map(t=>t.name);});}
async function saveMcp(){await run(async signal=>{await api(`${base.value}/mcp-resources`,signal,{receipt:receipt.value,allowedTools:allowed.value});if(signal.aborted)return;show.value=false;secret.value='';await read(signal);notice.value='已保存';});}
async function importSkill(){await run(async signal=>{let body:Record<string,unknown>;if(source.value==='git'){body={kind:'git',url:gitUrl.value,ref:gitRef.value,subpath:gitPath.value,operationId:operationId.value};}else{if(!file.value)throw new Error('请选择 Skill 文件');if(file.value.size>(source.value==='markdown'?65536:20*1024*1024))throw new Error('Skill 文件超过大小限制');if(source.value==='markdown'){await api(`${base.value}/skill-resources`,signal,{filename:file.value.name,content:await file.value.text(),operationId:operationId.value});if(signal.aborted)return;show.value=false;file.value=null;await read(signal);notice.value='已导入';return;}const bytes=new Uint8Array(await file.value.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=32768)binary+=String.fromCharCode(...bytes.subarray(offset,offset+32768));body={kind:'zip',data:btoa(binary),operationId:operationId.value};}await api(`${base.value}/skills/imports`,signal,body);if(signal.aborted)return;show.value=false;file.value=null;await read(signal);notice.value='已导入';});}
async function toggle(item:Resource){await run(async signal=>{await api(`${base.value}/${props.kind==='skills'?'skills':'mcp-resources'}/${encodeURIComponent(item.id)}/status`,signal,{enabled:!item.enabled,expectedVersion:item.revision??item.version},'PUT');await read(signal);});}
async function view(item:Resource){details.value=item;versions.value=[];detailError.value='';const expected=++detailRequest,current=generation,signal=controller.signal;if(props.kind!=='skills')return;detailLoading.value=true;try{const result=await api<{versions:ResourceVersion[]}>(`${base.value}/skills/${encodeURIComponent(item.id)}/versions`,signal);if(!signal.aborted&&expected===detailRequest&&current===generation)versions.value=result.versions;}catch(e){if(!signal.aborted&&expected===detailRequest){detailError.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(expected===detailRequest)detailLoading.value=false;}}

watch(()=>[props.workspaceId,props.kind],()=>{generation++;detailRequest++;detailLoading.value=false;controller.abort();controller=new AbortController();rows.value=[];query.value='';statusFilter.value='all';loaded.value=false;busy.value=false;show.value=false;details.value=null;secret.value='';void load();},{immediate:true});
onUnmounted(()=>{generation++;controller.abort();secret.value='';emit('busyChanged',false);});
</script>
<template><section class="resources">
 <div class="resource-toolbar"><div class="resource-search"><NInput v-if="rows.length" v-model:value="query" clearable :input-props="{ 'aria-label': `搜索${title}` }" :placeholder="`搜索${title}名称或说明`"/><InfoHint :label="`${title}使用说明`">{{kind==='skills'?'工作区维护可复用的 Skill，员工在能力包中引用。':'连接工具服务，再由员工能力包选择可用工具。'}}</InfoHint></div><NSelect v-if="rows.length" class="resource-status" v-model:value="statusFilter" aria-label="资源状态" :virtual-scroll="false" :options="[{ label: '全部状态', value: 'all' }, { label: '启用', value: 'enabled' }, { label: '停用', value: 'disabled' }]"/><NButton class="resource-refresh" :disabled="busy||disabled" @click="load">刷新</NButton><NButton type="primary" :disabled="busy||disabled" @click="open()">新增 {{title}}</NButton></div>
 <NAlert v-if="error" type="error" role="alert">{{error}}</NAlert><NAlert v-if="notice" type="success" role="status">{{notice}}</NAlert><p v-if="loading" role="status">正在读取 {{title}}…</p>
 <NEmpty v-if="loaded&&!loading&&!error&&!rows.length" :description="`尚未添加 ${title}`" />

 <NEmpty v-if="loaded && !error && rows.length && !filteredRows.length" description="没有符合条件的资源" />
 <div v-if="filteredRows.length" class="resource-browser" :class="{'has-detail':details&&!narrow}"><div class="resource-table-wrap"><table class="resource-table"><thead><tr><th scope="col">名称</th><th scope="col">{{ kind === 'skills' ? '用途' : '认证方式' }}</th><th scope="col">引用员工</th><th scope="col">{{ kind === 'skills' ? '版本' : '工具' }}</th><th scope="col">状态</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="item in filteredRows" :key="item.id" :class="{selected:details?.id===item.id}"><td data-label="名称"><strong>{{ item.name }}</strong></td><td :data-label="kind === 'skills' ? '用途' : '认证方式'">{{ kind === 'skills' ? item.description || '—' : item.auth?.kind ? ({ none: '无认证', bearer: 'Bearer令牌', header: '静态请求头' } as Record<string,string>)[item.auth.kind] || item.auth.kind : '未提供' }}</td><td data-label="引用员工">{{ item.references.map(row => row.name).join('、') || '暂无' }}</td><td :data-label="kind === 'skills' ? '版本' : '工具'">{{ kind === 'skills' ? `v${item.version}` : Array.isArray(item.tools) ? `${item.tools.length} 个工具` : '工具列表暂未提供' }}</td><td data-label="状态"><NTag :bordered="false" size="small" :type="item.enabled ? 'success' : 'default'">{{ item.enabled ? '启用' : '停用' }}</NTag></td><td data-label="操作"><NSpace :size="8"><NButton size="small" :disabled="busy || disabled" @click="view(item)">详情</NButton><NButton v-if="kind === 'mcp'" size="small" :disabled="busy || disabled" @click="open(item)">编辑</NButton><NPopconfirm :disabled="busy || disabled" @positive-click="toggle(item)"><template #trigger><NButton size="small" :disabled="busy || disabled">{{ item.enabled ? '停用' : '启用' }}</NButton></template>{{ item.enabled ? `停用“${item.name}”后，新的执行将无法使用它，已有任务不受影响。` : `启用“${item.name}”供后续执行使用。` }}</NPopconfirm></NSpace></td></tr></tbody></table></div><aside v-if="details&&!narrow" class="resource-detail-panel"><div class="resource-detail-actions"><NButton text size="small" aria-label="关闭资源详情" @click="details=null">关闭</NButton></div><ResourceDetails :resource="details" :kind="kind" :versions="versions" :loading="detailLoading" :error="detailError" @retry="view(details)"/></aside></div>
 <NDrawer :show="show" :width="'min(560px, 100vw)'" :close-on-esc="!busy" :mask-closable="!busy" @update:show="value=>{if(!value)close()}"><NDrawerContent :title="`${editing?'编辑':'新增'} ${title}`" closable><NForm @submit.prevent="kind==='skills'?importSkill():saveMcp()">
 <template v-if="kind==='skills'"><NFormItem label="导入方式"><NSelect aria-label="Skill导入方式" v-model:value="source" :disabled="busy" :options="[{label:'ZIP 完整技能包',value:'zip'},{label:'公开 Git 仓库',value:'git'},{label:'单 Markdown 文档',value:'markdown'}]" /></NFormItem>
 <template v-if="source==='git'"><NFormItem label="公开 HTTPS 仓库 URL"><NInput :input-props="{'aria-label':'Git仓库地址'}" v-model:value="gitUrl" :disabled="busy" placeholder="https://github.com/组织/仓库" /></NFormItem><NFormItem label="分支、标签或 commit"><NInput :input-props="{'aria-label':'Git分支或commit'}" v-model:value="gitRef" :disabled="busy" /></NFormItem><NFormItem label="Skill 子目录（可选）"><NInput :input-props="{'aria-label':'Git子目录'}" v-model:value="gitPath" :disabled="busy" placeholder="skills/example" /></NFormItem><p>支持 GitHub/GitLab 公开仓库，固定导入 commit。不使用本机登录凭据，不支持私仓、SSH、子模块或 LFS 自动拉取。</p></template>
 <template v-else><NFormItem label="Skill 文件"><input type="file" :accept="source==='zip'?'.zip':'.md'" :disabled="busy" aria-label="导入Skill文件" @change="selectFile" /></NFormItem><p>ZIP 只能有一个根目录，根内需有 skill.md（大小写兼容）；保留 scripts/assets 等附件。压缩20MiB、展开100MiB、最多1000文件，主文档64KiB。</p></template><NAlert type="info">导入会发布新版本，不执行脚本或安装依赖。同名 Skill 保留历史版本，下一执行会话使用新版本。</NAlert></template>
 <template v-else><NFormItem label="连接名称"><NInput :input-props="{'aria-label':'MCP连接名称'}" v-model:value="name" :disabled="busy" /></NFormItem><NFormItem label="Streamable HTTP 地址"><NInput :input-props="{'aria-label':'MCP地址'}" v-model:value="endpoint" :disabled="busy" placeholder="https://example.com/mcp" /></NFormItem><NFormItem label="认证方式"><NSelect aria-label="MCP认证方式" v-model:value="authKind" :disabled="busy" :options="[{label:'无认证',value:'none'},{label:'Bearer Token',value:'bearer'},{label:'静态 API Key Header',value:'header'}]" /></NFormItem><NFormItem v-if="authKind==='header'" label="Header 名称"><NInput :input-props="{'aria-label':'MCP认证Header'}" v-model:value="header" :disabled="busy" /></NFormItem><NFormItem v-if="authKind!=='none'" :label="editing?.auth?.configured?'新密钥（留空保留；地址变更须重新输入）':'密钥'"><NInput :input-props="{'aria-label':'MCP密钥',autocomplete:'new-password'}" v-model:value="secret" type="password" :disabled="busy" /></NFormItem><p>仅连接部署者允许的地址；认证信息加密保存，不回显。更新会影响引用它的员工后续执行。</p><NButton :disabled="busy||!name.trim()||!endpoint.trim()" @click="discover">连接并发现工具</NButton><NCheckboxGroup v-if="tools.length" v-model:value="allowed"><div v-for="tool in tools" :key="tool.name"><NCheckbox :value="tool.name" :disabled="busy">{{tool.name}}</NCheckbox><p>{{tool.description}}</p></div></NCheckboxGroup></template>
 <NAlert v-if="error" type="error" role="alert">{{error}}</NAlert><NSpace class="editor-actions"><NButton :disabled="busy" @click="close">取消</NButton><NButton type="primary" attr-type="submit" :loading="busy" :disabled="busy||disabled||(kind==='mcp'&&(!receipt||!allowed.length))||(kind==='skills'&&(source==='git'?!gitUrl.trim():!file))">{{kind==='skills'?'导入':'保存'}}</NButton></NSpace></NForm></NDrawerContent></NDrawer>
 <NDrawer :show="!!details&&narrow" :width="'min(560px, 100vw)'" @update:show="value=>{if(!value)details=null}"><NDrawerContent :title="details?.name??'资源详情'" closable><ResourceDetails v-if="details" :resource="details" :kind="kind" :versions="versions" :loading="detailLoading" :error="detailError" @retry="view(details)"/></NDrawerContent></NDrawer>
</section></template>
<style scoped>.resources{display:grid;gap:1rem;min-width:0}.resource-toolbar{display:flex;align-items:center;gap:.75rem;flex-wrap:wrap;margin-bottom:.25rem}.resource-search{display:flex;align-items:center;gap:.25rem;min-width:0;flex:1;max-width:30rem;margin-right:auto}.resource-status{width:10rem}.resource-browser{display:grid;gap:1rem;align-items:start;min-width:0}.resource-browser.has-detail{grid-template-columns:minmax(0,1.8fr) minmax(20rem,1fr)}.resource-detail-panel{min-width:0;border:1px solid var(--subtle);border-radius:.75rem;padding:1.25rem;background:var(--surface)}.resource-detail-actions{display:flex;justify-content:flex-end;margin:-.5rem -.5rem .25rem}.resource-table tr.selected{background:var(--tint)}.resource-table-wrap{min-width:0}.resource-refresh{justify-self:start}.resource-filters{display:grid;grid-template-columns:minmax(12rem,28rem) 11rem;gap:1rem;justify-content:space-between}.resource-table-wrap{overflow:auto;border:1px solid var(--subtle);border-radius:.75rem;background:var(--surface)}.resource-table{width:100%;border-collapse:collapse;font-size:.875rem}.resource-table th,.resource-table td{text-align:left;padding:.875rem 1rem;vertical-align:middle;border-bottom:1px solid var(--subtle)}.resource-table th{background:var(--background);color:var(--muted);font-weight:500;white-space:nowrap}.resource-table tr:last-child td{border-bottom:0}.resource-table td{overflow-wrap:anywhere}.resource-table td:first-child{min-width:10rem}.resource-table td:nth-child(2){max-width:22rem;color:var(--muted)}.resource-table td:last-child{min-width:11rem}.resource-heading{display:flex;justify-content:space-between;align-items:center;gap:1rem}.resources p{overflow-wrap:anywhere}.editor-actions{position:sticky;bottom:0;background:var(--surface);padding:1.25rem 0;margin-top:1.25rem}form{display:grid;gap:0.5rem}@media(max-width:74.99rem){.resource-browser.has-detail{grid-template-columns:1fr}}@media(max-width:47.5rem){.resource-search{flex-basis:100%;max-width:none}.resource-status{width:auto;flex:1}.resource-filters{grid-template-columns:1fr}.resource-table,.resource-table tbody,.resource-table tr{display:block}.resource-table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.resource-table tr{padding:.75rem 1rem;border-bottom:1px solid var(--subtle)}.resource-table tr:last-child{border-bottom:0}.resource-table tr td{display:flex;justify-content:space-between;gap:1rem;padding:.5rem 0;border:0;max-width:none;min-width:0}.resource-table td:before{content:attr(data-label);color:var(--muted);flex:none}.resource-table td:first-child{font-size:1rem}.resource-table td:first-child:before{display:none}.resource-table tr td:first-child,.resource-table tr td:last-child{min-width:0}.resource-table tr td:last-child{display:block}.resource-table td:last-child:before{display:none}.resource-heading{align-items:flex-start;flex-direction:column}}</style>
